<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                os.path.join(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/home/ubuntu/ros2_ws/src/large_models/large_models&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;vllm_gender_identification.py&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span></span>
